curl -s -X POST https://slack.com/api/conversations.list -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&types=public_channel&limit=100" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        if 'incident' in ch['name'].lower():
            print(json.dumps(ch, indent=2))
else:
    print(json.dumps(data, indent=2))
"

curl -s -X POST https://slack.com/api/conversations.history -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&channel=C_INC&limit=50" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    for msg in data['messages']:
        text = msg.get('text','')
        print(f\"ts={msg['ts']} user={msg['user']} text={text[:100]}\")
else:
    print(json.dumps(data, indent=2))
"

